MAP
	NAME "maptileviewer"
	IMAGETYPE PNG24
#	EXTENT 241856 6124877 402644 6307734
	EXTENT -20037508.3427892 -20037508.3427892 20037508.3427892 20037508.3427892  # world webmercator
	SIZE 1920 1920
#	SIZE 2160 1440
#	SIZE 3840 2160
	DEBUG 1
	PROJECTION
		"init=epsg:3857"
	END
	UNITS METERS

	OUTPUTFORMAT
		NAME "png"
		DRIVER "AGG/PNG"
		MIMETYPE "image/png"
		IMAGEMODE RGBA
	END

	WEB
		TEMPLATE  '/var/www/html/htdocs/mapserver/mapweb/maptileviewer.html'
		IMAGEPATH '/var/www/html/htdocs/mapserver/maptmp/' # filesystem path
		IMAGEURL  '/htdocs/mapserver/maptmp/'              # web browser path
		# Activate the layer as a WMS
		METADATA
			"wms_title" "WMS_MAPTILEVIEWER_RASTER"
			"wms_srs"   "EPSG:3857"
			"wms_enable_request" "*"
		END
	END

